export type ApprovedStampsProps = Record<string, any>;

const ApprovedStamps: React.FC<ApprovedStampsProps> = ({
  backgroundColor = "#002fa7",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#22c55e",
  stampText = "APPROVED",
  titleText = "INSTANT APPROVALS",
  subtitleText = "Get approved for homes, cars, and stores in seconds",
  iconColor = "#475569",
  clayColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Transparency Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animations (Slide in from top)
  const titleSpring = spring({
    frame,
    fps,
    config: { damping: 15, mass: 0.6 },
  });
  const titleY = interpolate(titleSpring, [0, 1], [-100, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);
  const subtitleOpacity = interpolate(frame, [10, 25], [0, 1], { extrapolateRight: "clamp" });

  // Sequential Step Timings
  const totalFrames = durationInSeconds * fps;
  const tStep1 = 0;
  const tStep2 = Math.floor(totalFrames * 0.31);
  const tStep3 = Math.floor(totalFrames * 0.62);

  // Vertical Row Placement Calculations
  const rowHeight = 180;
  const yRow1 = Math.floor(height * 0.25);
  const yRow2 = Math.floor(height * 0.48);
  const yRow3 = Math.floor(height * 0.71);
  const arrowHeight = yRow2 - (yRow1 + rowHeight);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      backgroundImage: `radial-gradient(circle at center, ${backgroundColor} 0%, #020617 100%)`,
      color: "#ffffff",
      overflow: "hidden",
      transition: "none"
    }}>
      {/* Title & Header Section */}
      <div style={{
        position: "absolute",
        top: height * 0.07,
        width: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        textAlign: "center",
        zIndex: 20,
        transform: `translate3d(0, ${titleY}px, 0)`,
        opacity: titleOpacity,
        transition: "none",
      }}>
        <h1 style={{
          fontFamily: spaceGrotesk,
          fontSize: "46px",
          fontWeight: 900,
          margin: 0,
          letterSpacing: "3px",
          color: "#ffffff",
          textShadow: "0 4px 12px rgba(0,0,0,0.3)",
          textTransform: "uppercase",
          transition: "none",
        }}>
          {titleText}
        </h1>
        <p style={{
          fontFamily: plusJakarta,
          fontSize: "20px",
          fontWeight: 500,
          margin: "10px 40px 0 40px",
          color: "#94a3b8",
          opacity: subtitleOpacity,
          lineHeight: 1.4,
          textShadow: "0 2px 6px rgba(0,0,0,0.2)",
          transition: "none",
        }}>
          {subtitleText}
        </p>
      </div>

      {/* Step 1: Home Approval Row */}
      <div style={{ position: "absolute", top: yRow1, width: "100%", height: rowHeight, transition: "none" }}>
        <ApprovedStampsRow
          type="home"
          frame={frame}
          fps={fps}
          startFrame={tStep1}
          width={width}
          height={height}
          primaryColor={primaryColor}
          stampText={stampText}
          iconColor={iconColor}
          clayColor={clayColor}
          arrowHeight={arrowHeight}
        />
      </div>

      {/* Step 2: Car Approval Row */}
      <div style={{ position: "absolute", top: yRow2, width: "100%", height: rowHeight, transition: "none" }}>
        <ApprovedStampsRow
          type="car"
          frame={frame}
          fps={fps}
          startFrame={tStep2}
          width={width}
          height={height}
          primaryColor={primaryColor}
          stampText={stampText}
          iconColor={iconColor}
          clayColor={clayColor}
          arrowHeight={arrowHeight}
        />
      </div>

      {/* Step 3: Store Approval Row */}
      <div style={{ position: "absolute", top: yRow3, width: "100%", height: rowHeight, transition: "none" }}>
        <ApprovedStampsRow
          type="store"
          frame={frame}
          fps={fps}
          startFrame={tStep3}
          width={width}
          height={height}
          primaryColor={primaryColor}
          stampText={stampText}
          iconColor={iconColor}
          clayColor={clayColor}
          arrowHeight={arrowHeight}
        />
      </div>
    </AbsoluteFill>
  );
};

export default ApprovedStamps;